    "description": "Pins the Anchor and SPL dependencies for the onchain program.",
    "content": "[package]\nname = \"firmware\"\nversion = \"0.1.0\"\nedition = \"2021\"\ndescription = \"Bounded agent capability registry, receipts and settlement on Solana\"\n\n[lib]\ncrate-type = [\"cdylib\", \"lib\"]\nname = \"firmware\"\n\n[features]\ndefault = []\ncpi = [\"no-entrypoint\"]\nno-entrypoint = []\nno-idl = []\nno-log-ix-name = []\nidl-build = [\"anchor-lang/idl-build\", \"anchor-spl/idl-build\"]\n\n[dependencies]\nanchor-lang = { version = \"1.2.0\", features = [\"init-if-needed\"] }\nanchor-spl = \"1.2.0\"\nsolana-sha256-hasher = \"3.0.0\"\n"
